"""
Runs tools/benchmark_overlap.bb with the GPU submission thread (the default) and without it (BLITZ_SYNC_GPU=1), for
several amounts of program logic per frame, and prints milliseconds per frame.

    python3 tools/benchmark_overlap.py [path to blitzcc] [work ...]

Without a display the programs run under xvfb-run (llvmpipe, where the CPU is also the GPU: the overlap is then mostly
a matter of free cores).
"""
import os
import re
import shutil
import statistics
import subprocess
import sys
import tempfile


def main():
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    args = sys.argv[1:]
    compiler = args.pop(0) if args and os.path.isfile(args[0]) else os.path.join(root, "build", "code_compiler", "blitzcc")
    works = [int(a) for a in args] or [0, 20000, 100000, 400000]
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") else ["xvfb-run", "-a"]
    if runner and not shutil.which("xvfb-run"):
        sys.exit("There is no display and no xvfb-run.")
    runs = int(os.environ.get("BENCH_RUNS", "3"))
    with tempfile.TemporaryDirectory() as directory:
        program = os.path.join(directory, "benchmark")
        subprocess.run([compiler, os.path.join(root, "tools", "benchmark_overlap.bb"), "-o", program], check=True, stdout=subprocess.DEVNULL)
        print("%-10s %12s %12s %9s" % ("work", "thread ms", "sync ms", "gain"))
        for work in works:
            results = {}
            for mode in ("thread", "sync"):
                env = dict(os.environ, BENCH_WORK=str(work))
                env.pop("BLITZ_SYNC_GPU", None) # What was set in the shell would make both modes the same.
                if mode == "sync":
                    env["BLITZ_SYNC_GPU"] = "1"
                times = []
                for _ in range(runs):
                    result = subprocess.run(runner + [program], env=env, capture_output=True, text=True, timeout=600)
                    match = re.search(r"ms_per_frame=([\d.]+)", result.stdout + result.stderr)
                    if match:
                        times.append(float(match.group(1)))
                results[mode] = statistics.median(times) if times else float("nan")
            print("%-10d %12.2f %12.2f %8.1f%%" % (work, results["thread"], results["sync"], (results["sync"] - results["thread"]) / results["sync"] * 100))


main()
